package edu.pitt.isl.mobileclaw.notiftest.skills.messaging

import java.io.ByteArrayOutputStream

/**
 * The small MMS subset this tool sends: one JPEG, optional UTF-8 text, and a SMIL
 * presentation. SmsManager consumes an encoded M-Send.req, not the JPEG's URI.
 *
 * WSP/MMS field encodings follow AOSP PduComposer/PduPart (Messaging commit
 * de315b762312dd1a5d2bbd16e62ef2bd123f61e5). The golden test is generated by that
 * independent composer. No hidden framework API or default-SMS role is needed.
 */
internal object PhotoMmsPdu {
    fun encode(to: String, jpeg: ByteArray, body: String, transactionId: String): ByteArray {
        require(Regex("\\+?[0-9]{7,15}").matches(to)) { "Invalid recipient" }
        require(Regex("[A-Za-z0-9-]{1,80}").matches(transactionId)) { "Invalid transaction id" }
        require(jpeg.isNotEmpty()) { "Empty photo" }
        require(body.toByteArray(Charsets.UTF_8).size <= 8_000) { "Message text is too long" }
        val parts = buildList {
            add(Part("application/smil", "smil.xml", "smil", smil(body.isNotEmpty()).toByteArray(), false))
            add(Part("image/jpeg", "photo.jpg", "photo", jpeg, false))
            if (body.isNotEmpty()) add(Part("text/plain", "text.txt", "text", body.toByteArray(Charsets.UTF_8), true))
        }
        return bytes {
            write(0x8c); write(0x80) // X-Mms-Message-Type: m-send-req
            write(0x98); text(transactionId)
            write(0x8d); write(0x92) // MMS 1.2
            write(0x89); write(1); write(0x81) // From: insert-address-token
            write(0x97)
            value(bytes { write(0xea); text("$to/TYPE=PLMN") }) // UTF-8 encoded address
            write(0x8a); write(0x80) // personal
            write(0x8f); write(0x81) // normal priority
            write(0x86); write(0x81) // no delivery report requested
            write(0x90); write(0x81) // no read report requested
            write(0x84)
            value(bytes {
                write(0xb3) // application/vnd.wap.multipart.related
                write(0x8a); text("<smil>")
                write(0x89); text("application/smil")
            })
            uintvar(parts.size)
            for (part in parts) {
                val headers = bytes {
                    value(bytes {
                        when (part.mime) {
                            "image/jpeg" -> write(0x9e)
                            "text/plain" -> write(0x83)
                            else -> text(part.mime)
                        }
                        write(0x85); text(part.filename)
                        if (part.utf8) { write(0x81); write(0xea) }
                    })
                    write(0xc0); write(0x22); text("<${part.id}>")
                    write(0x8e); text(part.filename)
                }
                uintvar(headers.size); uintvar(part.data.size)
                write(headers); write(part.data)
            }
        }
    }

    internal fun smil(withText: Boolean) =
        "<smil><head><layout><root-layout width=\"320\" height=\"480\"/>" +
            "<region id=\"Image\" left=\"0\" top=\"0\" width=\"320\" height=\"400\" fit=\"meet\"/>" +
            "<region id=\"Text\" left=\"0\" top=\"400\" width=\"320\" height=\"80\"/>" +
            "</layout></head><body><par dur=\"5000ms\"><img src=\"photo.jpg\" region=\"Image\"/>" +
            (if (withText) "<text src=\"text.txt\" region=\"Text\"/>" else "") +
            "</par></body></smil>"

    private data class Part(val mime: String, val filename: String, val id: String, val data: ByteArray, val utf8: Boolean)

    private inline fun bytes(write: ByteArrayOutputStream.() -> Unit): ByteArray =
        ByteArrayOutputStream().apply(write).toByteArray()

    private fun ByteArrayOutputStream.text(text: String) {
        require('\u0000' !in text)
        val data = text.toByteArray(Charsets.UTF_8)
        if (data.isNotEmpty() && (data[0].toInt() and 0xff) >= 128) write(0x7f)
        write(data); write(0)
    }

    private fun ByteArrayOutputStream.value(value: ByteArray) {
        if (value.size <= 30) write(value.size) else { write(31); uintvar(value.size) }
        write(value)
    }

    private fun ByteArrayOutputStream.uintvar(value: Int) {
        require(value >= 0)
        // Preserve AOSP's extra leading zero group at exact all-one boundaries
        // (127, 16383, ...), as well as the ordinary WSP continuation encoding.
        var shift = 0
        var maximum = 127L
        while (value.toLong() >= maximum && shift < 28) {
            shift += 7
            maximum = (maximum shl 7) or 127
        }
        while (shift > 0) { write(((value ushr shift) and 0x7f) or 0x80); shift -= 7 }
        write(value and 0x7f)
    }
}
